//! CPU-baked studio environment for image-based lighting.
//!
//! Ported from `Engine/Sources/RenderBackend/Core/Lighting/EnvironmentIBL.swift`.
//! Prefiltered the way real engines do it (learnopengl / Karis split-sum, as
//! used by UE & Godot): the specular mip chain is generated by **GGX importance
//! sampling** of the environment per roughness level (not a box blur), so
//! reflections blur physically with roughness. mip 0 is the sharp mirror, mip N
//! is roughness N/(mipCount-1), and the most-blurred mip doubles as diffuse
//! irradiance. Stored as an equirectangular rgba16Float texture; a dark studio
//! with bright HDR soft-boxes is what makes polished metal read as
//! gunmetal/chrome.

use std::sync::OnceLock;

use diffuse_math::simd::simd_compat::{Float2, Float3, simd_cross, simd_dot, simd_normalize};

/// The studio is fixed. Share immutable CPU pixels across renderer sessions;
/// each Device still owns and uploads its own GPU texture. Swift initializes
/// this once, including when scene workers start concurrently — `OnceLock` is
/// the Rust equivalent of a `static let` with thread-safe lazy evaluation.
static LEVELS: OnceLock<Vec<MipLevel>> = OnceLock::new();

pub enum StudioEnvironmentIBL {}

impl StudioEnvironmentIBL {
    pub const BASE_WIDTH: usize = 512;
    pub const BASE_HEIGHT: usize = 256;
    pub const MIP_COUNT: usize = 6; // roughness 0 … 1 across the chain
    pub const MAX_LOD: f32 = 5.0; // mipCount - 1
    pub const PREFILTER_SAMPLES: usize = 32;

    /// `static let levels = generate()` — computed once per process.
    pub fn levels() -> &'static [MipLevel] {
        LEVELS.get_or_init(generate)
    }

    /// IEEE-754 binary32 → binary16 for the positive HDR values here.
    pub fn float_to_half(value: f32) -> u16 {
        let bits = value.to_bits();
        let sign = ((bits >> 16) & 0x8000) as u16;
        let exponent = ((bits >> 23) & 0xFF) as i64 - 127 + 15;
        let mantissa = bits & 0x007F_FFFF;
        if exponent <= 0 {
            return sign;
        }
        if exponent >= 31 {
            return sign | 0x7C00;
        }
        sign | ((exponent as u16) << 10) | ((mantissa >> 13) as u16)
    }
}

/// One prefiltered mip level of the environment.
#[derive(Clone, Debug, PartialEq)]
pub struct MipLevel {
    pub width: usize,
    pub height: usize,
    pub half_rgba: Vec<u16>,
}

impl MipLevel {
    pub fn new(width: usize, height: usize, half_rgba: Vec<u16>) -> Self {
        MipLevel {
            width,
            height,
            half_rgba,
        }
    }
}

fn generate() -> Vec<MipLevel> {
    let mut levels: Vec<MipLevel> = Vec::new();
    for level in 0..StudioEnvironmentIBL::MIP_COUNT {
        let w = 1usize.max(StudioEnvironmentIBL::BASE_WIDTH >> level);
        let h = 1usize.max(StudioEnvironmentIBL::BASE_HEIGHT >> level);
        let roughness = level as f32 / (StudioEnvironmentIBL::MIP_COUNT - 1) as f32;
        let mut half = vec![0u16; w * h * 4];
        for y in 0..h {
            for x in 0..w {
                let u = (x as f32 + 0.5) / w as f32;
                let v = (y as f32 + 0.5) / h as f32;
                let dir = direction(u, v);
                let c = if level == 0 {
                    radiance(dir)
                } else {
                    prefilter(dir, roughness)
                };
                let i = (y * w + x) * 4;
                half[i] = StudioEnvironmentIBL::float_to_half(c.x);
                half[i + 1] = StudioEnvironmentIBL::float_to_half(c.y);
                half[i + 2] = StudioEnvironmentIBL::float_to_half(c.z);
                half[i + 3] = StudioEnvironmentIBL::float_to_half(1.0);
            }
        }
        levels.push(MipLevel::new(w, h, half));
    }
    levels
}

// MARK: - GGX prefilter (split-sum specular IBL)

/// Prefilter the environment around `normal` for `roughness`, integrating the
/// GGX specular lobe via importance sampling (Karis 2013 / learnopengl).
fn prefilter(normal: Float3, roughness: f32) -> Float3 {
    let v = normal; // common N=V=R assumption for prefiltering
    let mut color = Float3::ZERO;
    let mut total_weight: f32 = 0.0;
    for i in 0..StudioEnvironmentIBL::PREFILTER_SAMPLES {
        let xi = hammersley(i, StudioEnvironmentIBL::PREFILTER_SAMPLES);
        let h = importance_sample_ggx(xi, normal, roughness);
        let l = simd_normalize(2.0 * simd_dot(v, h) * h - v);
        let n_dot_l = simd_dot(normal, l);
        if n_dot_l > 0.0 {
            color += radiance(l) * n_dot_l;
            total_weight += n_dot_l;
        }
    }
    if total_weight > 0.0 {
        color / total_weight
    } else {
        radiance(normal)
    }
}

fn radical_inverse_vd_c(bits: u32) -> f32 {
    let mut b = bits;
    b = (b << 16) | (b >> 16);
    b = ((b & 0x5555_5555) << 1) | ((b & 0xAAAA_AAAA) >> 1);
    b = ((b & 0x3333_3333) << 2) | ((b & 0xCCCC_CCCC) >> 2);
    b = ((b & 0x0F0F_0F0F) << 4) | ((b & 0xF0F0_F0F0) >> 4);
    b = ((b & 0x00FF_00FF) << 8) | ((b & 0xFF00_FF00) >> 8);
    b as f32 * 2.328_306_4e-10
}

fn hammersley(i: usize, n: usize) -> Float2 {
    Float2::new(i as f32 / n as f32, radical_inverse_vd_c(i as u32))
}

fn importance_sample_ggx(xi: Float2, n: Float3, roughness: f32) -> Float3 {
    let a = roughness * roughness;
    let phi = 2.0 * core::f32::consts::PI * xi.x;
    let cos_theta = ((1.0 - xi.y) / (1.0 + (a * a - 1.0) * xi.y)).sqrt();
    let sin_theta = (1.0 - cos_theta * cos_theta).max(0.0).sqrt();
    // Half-vector in tangent space, then to world around N.
    let h_t = Float3::new(phi.cos() * sin_theta, phi.sin() * sin_theta, cos_theta);
    let up = if n.z.abs() < 0.999 {
        Float3::new(0.0, 0.0, 1.0)
    } else {
        Float3::new(1.0, 0.0, 0.0)
    };
    let tangent = simd_normalize(simd_cross(up, n));
    let bitangent = simd_cross(n, tangent);
    simd_normalize(tangent * h_t.x + bitangent * h_t.y + n * h_t.z)
}

// MARK: - Environment definition

/// Equirect (u, v) → world direction. Matches `equirect_uv` in mesh.wgsl.
fn direction(u: f32, v: f32) -> Float3 {
    let phi = (u - 0.5) * 2.0 * core::f32::consts::PI;
    let theta = v * core::f32::consts::PI;
    let sin_theta = theta.sin();
    Float3::new(sin_theta * phi.cos(), theta.cos(), sin_theta * phi.sin())
}

fn radiance(dir: Float3) -> Float3 {
    // BRIGHT, fairly even studio so the material is clearly visible — this is
    // an asset viewer (Sketchfab/UE preview), not a dark glamour shot. A
    // mirror metal reflects this, so a bright dome makes the body read as a
    // legible mid-tone metal rather than a black void, while a soft top→floor
    // gradient + soft-boxes keep enough directional variation to read as
    // metal and provide bright highlights.
    // Studio with REAL vertical contrast — a dim floor brightening to a lit
    // ceiling. A uniform dome makes glossy metal a flat grey ("white model");
    // this gradient gives a clear dark-underside / bright-top reflection so
    // the metal reads as a 3D reflective object, plus a big bright key
    // soft-box as the dominant highlight (the hallmark of polished metal).
    let y = dir.y;
    let floor_color = Float3::new(0.05, 0.05, 0.055);
    let horizon_color = Float3::new(0.22, 0.225, 0.245);
    let ceil_color = Float3::new(0.55, 0.565, 0.62);
    let mut c = if y >= 0.0 {
        horizon_color + (ceil_color - horizon_color) * smoothstep(0.0, 1.0, y)
    } else {
        horizon_color + (floor_color - horizon_color) * smoothstep(0.0, 1.0, -y)
    };
    // Large bright key soft-box (broad → a big soft reflection) + fills.
    c += softbox(
        dir,
        simd_normalize(Float3::new(0.35, 0.50, 0.75)),
        0.74,
        0.93,
        Float3::new(15.0, 15.0, 14.0),
    ); // key (broad, bright)
    c += softbox(
        dir,
        simd_normalize(Float3::new(-0.62, 0.42, 0.20)),
        0.88,
        0.97,
        Float3::new(3.2, 3.5, 4.2),
    ); // fill (cool)
    c += softbox(
        dir,
        simd_normalize(Float3::new(0.10, 0.32, -0.92)),
        0.90,
        0.98,
        Float3::new(4.2, 3.9, 3.4),
    ); // rim (warm)
    c
}

fn softbox(dir: Float3, center: Float3, inner: f32, outer: f32, color: Float3) -> Float3 {
    color * smoothstep(inner, outer, simd_dot(dir, center))
}

fn smoothstep(edge0: f32, edge1: f32, x: f32) -> f32 {
    let t = 1.0f32.min(0.0f32.max((x - edge0) / (edge1 - edge0).max(1e-5)));
    t * t * (3.0 - 2.0 * t)
}
